begin;
insert into auth.users(id,email) values('f2000000-0000-4000-8000-000000000001','starting-owner@example.invalid'),('f2000000-0000-4000-8000-000000000002','starting-other@example.invalid');
set local role authenticated;
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
do $$
declare h uuid; h2 uuid; category uuid; income_category uuid; second_category uuid; a uuid; b uuid; other_account uuid; e1 uuid; e2 uuid; foreign_entry uuid; tx uuid; count_before integer; rejected boolean; n integer; people jsonb:='[{"name":"Moi","relationship":"self","isPrimary":true}]';accounts jsonb;
begin
 accounts:=(select jsonb_agg(jsonb_build_object('name',type,'account_type',type,'balance_cents',amount,'balance_date',current_date::text)) from (values('checking',100000),('cash',20000),('savings',500000),('investment',1000000),('crypto',50000),('credit',-300000)) a(type,amount));
 h:=public.configure_household_with_accounts(null,'Starting fixture','["Salaire"]','["Courses","Loisirs"]',people,accounts,jsonb_build_object('month',date_trunc('month',current_date)::date,'income_cents',300000,'expense_cents',200000));
 if (select count(*) from public.bank_accounts where household_id=h)<>6 then raise exception 'Starting assets missing';end if;
 if exists(select 1 from public.entries where household_id=h) then raise exception 'Starting wealth was treated as income';end if;
 if (select income_cents from public.monthly_budgets where household_id=h)<>300000 then raise exception 'Initial plan missing';end if;
 select count(*) into count_before from public.households;
 rejected:=false;
 begin perform public.configure_household_with_accounts(null,'Invalid cash','["Salaire"]','["Courses"]',people,jsonb_build_array(jsonb_build_object('name','Invalid','account_type','cash','balance_cents',-100,'balance_date',current_date::text)),null);exception when check_violation then rejected:=true;end;
 if not rejected or (select count(*) from public.households)<>count_before then raise exception 'Invalid starting finances did not roll back';end if;
 select id into category from public.categories where household_id=h and name='Courses';
 select id into second_category from public.categories where household_id=h and name='Loisirs';
 select id into income_category from public.categories where household_id=h and kind='income';
 select id into a from public.bank_accounts where household_id=h and account_type='checking';
 select id into b from public.bank_accounts where household_id=h and account_type='cash';
 insert into public.entries(household_id,category_id,kind,label,amount_cents,entry_date) values(h,category,'expense','One',100,current_date) returning id into e1;
 insert into public.entries(household_id,category_id,kind,label,amount_cents,entry_date) values(h,category,'expense','Two',200,current_date) returning id into e2;
 n:=public.bulk_manage_entries(h,array[e1,e2],'category',second_category::text);
 if n<>2 or (select count(*) from public.entries where id in(e1,e2) and category_id=second_category)<>2 then raise exception 'Bulk category failed';end if;
 rejected:=false;
 begin perform public.bulk_manage_entries(h,array[e1,e2],'category',income_category::text);exception when check_violation then rejected:=true;end;
 if not rejected then raise exception 'Wrong-kind category accepted';end if;
 n:=public.bulk_manage_entries(h,array[e1,e2],'flow','investment');
 if (select sum(amount_cents) from public.entries where household_id=h and flow_type='investment')<>300 then raise exception 'Investment classification failed';end if;
 perform set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000002',true);
 h2:=public.configure_household_with_accounts(null,'Other fixture','["Salaire"]','["Courses"]',people,jsonb_build_array(jsonb_build_object('name','Other','account_type','cash','balance_cents',100,'balance_date',current_date::text)),null);
 select id into other_account from public.bank_accounts where household_id=h2;
 insert into public.entries(household_id,category_id,kind,label,amount_cents,entry_date) select h2,id,'expense','Other',100,current_date from public.categories where household_id=h2 and kind='expense' returning id into foreign_entry;
 perform set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
 rejected:=false;
 begin perform public.bulk_manage_entries(h,array[e1,foreign_entry],'delete');exception when insufficient_privilege then rejected:=true;end;
 if not rejected or not exists(select 1 from public.entries where id=e1) then raise exception 'Bulk access was not atomic';end if;
 rejected:=false;
 begin perform public.delete_manual_accounts(h,array[a,other_account]);exception when insufficient_privilege then rejected:=true;end;
 if not rejected or not exists(select 1 from public.bank_accounts where id=a) then raise exception 'Account batch isolation failed';end if;
 perform public.import_bank_transactions(a,jsonb_build_array(jsonb_build_object('fingerprint','starting:import','transaction_date',current_date,'label','Imported','amount_cents',-100,'currency','EUR','category_id',category)));
 select id into tx from public.bank_transactions where bank_account_id=a;
 perform public.bulk_manage_entries(h,array[(select id from public.entries where bank_transaction_id=tx)],'delete');
 if exists(select 1 from public.bank_transactions where id=tx) then raise exception 'Deleted imported entry left bank transaction behind';end if;
 perform public.delete_manual_accounts(h,array[a,b]);
 if (select count(*) from public.bank_accounts where household_id=h)<>4 then raise exception 'Selected accounts were not deleted';end if;
 if (select count(*) from public.entries where household_id=h)<>2 then raise exception 'Unlinked manual entries were deleted';end if;
end;
$$;
rollback;
